/*
Theme Name: IMC Calculadora (Kadence Child)
Theme URI: https://imccalculadora.app
Description: Child theme of Kadence for IMC Calculadora — houses all custom CSS and structural overrides for the Clinical Precision design.
Author: IMC Calculadora
Template: kadence
Version: 1.1.2
Text Domain: imc-calculadora-child
*/
/* ===== Clinical Precision — sitewide CSS ===== */

/* Body measure & rhythm for prose */
.entry-content > p,
.entry-content > ul,
.entry-content > ol {
	max-width: 68ch;
}

/* Hairline dividers instead of shadows, site-wide */
.entry-content hr {
	border: none;
	border-top: 1px solid #DCE3E1;
	margin: 32px 0;
}

/* FAQ / accordion blocks: hairline separators, no shadow */
.wp-block-kadence-accordion,
.kt-accordion-wrap .kt-accordion-panel-trigger {
	box-shadow: none !important;
}
.kt-accordion-wrap .kt-blocks-accordion-item {
	border: none !important;
	border-bottom: 1px solid #DCE3E1 !important;
	border-radius: 0 !important;
}

/* Tables: flat, hairline */
.entry-content table {
	border-collapse: collapse;
	box-shadow: none;
}
.entry-content table th,
.entry-content table td {
	border: 1px solid #DCE3E1;
}
.entry-content table th {
	background: var(--global-palette8);
	color: var(--global-palette3);
	font-family: "Space Grotesk", sans-serif;
	font-weight: 600;
}

/* Remove default card shadows everywhere except the calculator */
.kadence-column_wrap,
.wp-block-kadence-infobox .kt-blocks-info-box-link,
.wp-block-kadence-column {
	box-shadow: none !important;
}

/* ===================================================== */
/* Calculator "instrument panel" — the one place a shadow is allowed */
/* ===================================================== */
.imc-calc {
	background: var(--global-palette9);
	border: 1px solid #DCE3E1;
	border-radius: 6px;
	padding: 32px;
	box-shadow: 0 1px 2px rgba(14, 92, 82, 0.06), 0 12px 28px -8px rgba(14, 92, 82, 0.14);
	max-width: 560px;
	margin: 0 auto;
}

@media (max-width: 599px) {
	.imc-calc {
		padding: 20px;
	}
}

/* Hidden unit fields must stay hidden even if a layout rule sets display. */
.imc-calc [hidden] {
	display: none !important;
}

/* Unit toggle — segmented control */
.imc-calc__unit-toggle {
	display: flex;
	gap: 4px;
	background: var(--global-palette8);
	border: 1px solid #DCE3E1;
	border-radius: 6px;
	padding: 4px;
	margin-bottom: 20px;
}
.imc-calc__unit-btn {
	flex: 1;
	border: none;
	background: transparent;
	color: var(--global-palette5);
	font-family: "IBM Plex Sans", sans-serif;
	font-weight: 500;
	font-size: 14px;
	padding: 10px 12px;
	border-radius: 4px;
	cursor: pointer;
	transition: background 0.15s ease, color 0.15s ease;
}
.imc-calc__unit-btn.is-active {
	background: var(--global-palette9);
	color: var(--global-palette1);
	box-shadow: 0 1px 2px rgba(14, 92, 82, 0.10);
}

/* Fields */
.imc-calc__fields {
	display: grid;
	gap: 16px;
	margin-bottom: 20px;
}
.imc-calc__field label {
	display: block;
	font-family: "IBM Plex Sans", sans-serif;
	font-weight: 500;
	font-size: 14px;
	color: var(--global-palette4);
	margin-bottom: 6px;
}
.imc-calc__field input[type="number"],
.imc-calc__field select {
	width: 100%;
	box-sizing: border-box;
	min-height: 48px;
	padding: 12px 14px;
	font-family: "IBM Plex Sans", sans-serif;
	font-size: 16px;
	color: var(--global-palette3);
	background: var(--global-palette9);
	border: 1px solid #DCE3E1;
	border-radius: 6px;
	transition: border-color 0.15s ease, box-shadow 0.15s ease;
}
.imc-calc__field input[type="number"]:focus,
.imc-calc__field select:focus,
.imc-calc__unit-btn:focus-visible,
.imc-calc__submit:focus-visible {
	outline: none;
	border-color: var(--global-palette1);
	box-shadow: 0 0 0 3px rgba(14, 92, 82, 0.18);
}
.imc-calc__ftin {
	display: flex;
	align-items: center;
	gap: 8px;
}
.imc-calc__ftin input {
	width: 100%;
}
.imc-calc__ftin span {
	font-size: 13px;
	color: var(--global-palette5);
	white-space: nowrap;
}

/* Submit button — solid teal accent, 6px radius, no shadow, sentence case */
.imc-calc__submit {
	display: block;
	width: 100%;
	background: var(--global-palette1);
	color: var(--global-palette9);
	border: none;
	border-radius: 6px;
	padding: 14px 20px;
	font-family: "IBM Plex Sans", sans-serif;
	font-weight: 600;
	font-size: 16px;
	text-transform: none;
	box-shadow: none;
	cursor: pointer;
	transition: background 0.15s ease;
}
.imc-calc__submit:hover {
	background: var(--global-palette2);
}

/* Result panel */
.imc-calc__result {
	margin-top: 24px;
	padding-top: 24px;
	border-top: 1px solid #DCE3E1;
	text-align: center;
}
.imc-calc__result-number {
	font-family: "Space Grotesk", sans-serif;
	font-weight: 600;
	font-size: 48px;
	line-height: 1.1;
	color: var(--global-palette3);
}
.imc-calc__result-sub {
	font-family: "IBM Plex Sans", sans-serif;
	font-size: 14px;
	color: var(--global-palette5);
	margin-top: 4px;
}

/* Category — colored pill (category-scale swatch, inline background set per-result) */
.imc-calc__result-category {
	display: inline-block;
	margin-top: 12px;
	padding: 6px 16px;
	border-radius: 999px;
	color: #ffffff;
	font-family: "IBM Plex Sans", sans-serif;
	font-weight: 600;
	font-size: 14px;
}

.imc-calc__result-message {
	margin-top: 16px;
	font-family: "IBM Plex Sans", sans-serif;
	font-size: 15px;
	line-height: 1.6;
	color: var(--global-palette4);
}

.imc-calc__error {
	margin-top: 16px;
	color: #A83A2A;
	font-family: "IBM Plex Sans", sans-serif;
	font-size: 14px;
}

.imc-calc__disclaimer {
	margin-top: 20px;
	padding-top: 16px;
	border-top: 1px solid #DCE3E1;
	font-size: 12px;
	line-height: 1.5;
	color: var(--global-palette6);
}

/* Percentile bar (children's calculator) */
.imc-calc__percentile-bar {
	margin-top: 16px;
}
.imc-calc__percentile-track {
	position: relative;
	height: 8px;
	border-radius: 4px;
	background: linear-gradient(to right, #3B7DD8, #0E5C52 35%, #C98A1F 65%, #C1591F 85%, #A83A2A);
}
.imc-calc__percentile-marker {
	position: absolute;
	top: -4px;
	width: 16px;
	height: 16px;
	border-radius: 50%;
	background: var(--global-palette9);
	border: 3px solid var(--global-palette3);
	transform: translateX(-50%);
}
.imc-calc__percentile-scale {
	display: flex;
	justify-content: space-between;
	margin-top: 6px;
	font-size: 11px;
	color: var(--global-palette6);
}

/* Footer polish */
#colophon .imc-calc__disclaimer { display: none; }
.footer-navigation ul.menu {
	justify-content: center;
}

/* Sticky header shadow-free hairline */
.site-header.is-sticky {
	box-shadow: 0 1px 0 #DCE3E1;
}

/* One H1 per page: the Kadence content heading. Hide the theme title banner. */
.page .entry-header.page-title,
.home .entry-header.page-title {
	display: none;
}


/* Neutralize WordPress core default purple presets (unused, but override to stay on-palette) */
:root {
	--wp--preset--color--vivid-purple: #3B5B6D;
	--wp--preset--gradient--vivid-cyan-blue-to-vivid-purple: linear-gradient(135deg, rgb(14,92,82) 0%, rgb(59,91,109) 100%);
	--wp--preset--gradient--luminous-dusk: linear-gradient(135deg, rgb(59,125,216) 0%, rgb(59,91,109) 50%, rgb(14,92,82) 100%);
	--wp--preset--gradient--blush-light-purple: linear-gradient(135deg, rgb(220,227,225) 0%, rgb(59,91,109) 100%);
}

/* Neutralize remaining core/plugin-embedded purple swatches (unused on this site, present only as inert CSS) */
:root {
	--wp-block-synced-color: #0E5C52 !important;
	--wp-block-synced-color--rgb: 14, 92, 82 !important;
}
.has-purple-crush-gradient-background {
	background: linear-gradient(135deg, #0E5C52, #3B5B6D 100%) !important;
}
.has-nightshade-gradient-background {
	background: linear-gradient(135deg, #0E5C52, #3B7DD8 100%) !important;
}

/* ===================================================== */
/* Long-form content polish — turn the plain block stream */
/* into a structured, professional reading experience     */
/* ===================================================== */

.entry-content {
	--content-measure: 68ch;
}

/* Section rhythm: every H2 starts a new "section" with breathing room + a subtle rule above it (except the first) */
.entry-content h2 {
	margin-top: 64px;
	margin-bottom: 20px;
	padding-top: 32px;
	border-top: 1px solid #DCE3E1;
	max-width: var(--content-measure);
}
.entry-content > .wp-block-heading:first-of-type,
.entry-content h2:first-child {
	border-top: none;
	padding-top: 0;
	margin-top: 8px;
}
.entry-content h3 {
	margin-top: 36px;
	margin-bottom: 12px;
	max-width: var(--content-measure);
}
.entry-content p {
	max-width: var(--content-measure);
}

/* Lists: give them a teal marker instead of default bullets/decimal grey */
.entry-content ul:not(.wp-block-kadence-icon-list-container):not(.footer-navigation ul):not(.menu) {
	max-width: var(--content-measure);
	padding-left: 0;
	list-style: none;
}
.entry-content ul:not(.wp-block-kadence-icon-list-container):not(.footer-navigation ul):not(.menu) > li {
	position: relative;
	padding-left: 28px;
	margin-bottom: 10px;
	line-height: 1.6;
}
.entry-content ul:not(.wp-block-kadence-icon-list-container):not(.footer-navigation ul):not(.menu) > li::before {
	content: "";
	position: absolute;
	left: 0;
	top: 0.55em;
	width: 8px;
	height: 8px;
	border-radius: 2px;
	background: var(--global-palette1);
}
.entry-content ol {
	max-width: var(--content-measure);
	padding-left: 22px;
}
.entry-content ol > li {
	padding-left: 6px;
	margin-bottom: 10px;
	line-height: 1.6;
}
.entry-content ol > li::marker {
	color: var(--global-palette1);
	font-family: "Space Grotesk", sans-serif;
	font-weight: 600;
}

/* FAQ accordion (native <details>/<summary>) — instrument-panel styling instead of the browser default disclosure triangle */
.entry-content details {
	max-width: var(--content-measure);
	border: 1px solid #DCE3E1;
	border-radius: 6px;
	margin-bottom: 10px;
	background: var(--global-palette9);
	overflow: hidden;
}
.entry-content details + details {
	margin-top: -1px;
}
.entry-content details summary {
	list-style: none;
	cursor: pointer;
	padding: 16px 44px 16px 18px;
	font-family: "IBM Plex Sans", sans-serif;
	font-weight: 600;
	font-size: 16px;
	color: var(--global-palette3);
	position: relative;
	line-height: 1.4;
}
.entry-content details summary::-webkit-details-marker {
	display: none;
}
.entry-content details summary::after {
	content: "+";
	position: absolute;
	right: 18px;
	top: 50%;
	transform: translateY(-50%);
	font-family: "Space Grotesk", sans-serif;
	font-size: 20px;
	font-weight: 600;
	color: var(--global-palette1);
	transition: transform 0.15s ease;
}
.entry-content details[open] summary::after {
	transform: translateY(-50%) rotate(45deg);
}
.entry-content details summary:hover {
	background: var(--global-palette8);
}
.entry-content details[open] summary {
	border-bottom: 1px solid #DCE3E1;
}
.entry-content details p {
	padding: 14px 18px 18px;
	margin: 0;
	color: var(--global-palette4);
	line-height: 1.65;
	max-width: none;
}

/* Table refinement */
.entry-content .wp-block-table {
	max-width: var(--content-measure);
	overflow-x: auto;
}
.entry-content table {
	width: 100%;
	border-radius: 6px;
	overflow: hidden;
}
.entry-content table td {
	padding: 10px 14px;
	color: var(--global-palette4);
}
.entry-content table th {
	padding: 10px 14px;
	text-align: left;
}
.entry-content table tbody tr:nth-child(even) td {
	background: var(--global-palette8);
}

/* Tool-link columns only. Section columns stay flat. */
.imc-tools .wp-block-kadence-column {
	background: var(--global-palette9);
	border: 1px solid #DCE3E1;
	border-radius: 6px;
	padding: 24px;
	transition: border-color 0.15s ease;
}
.imc-tools .wp-block-kadence-column:hover {
	border-color: var(--global-palette1);
}
.imc-tools .wp-block-kadence-column p {
	max-width: none;
}
.imc-tools .kt-btn-inner-text {
	font-weight: 600;
}

/* Full-bleed Kadence sections inside the normal content column */
.entry-content > .alignfull,
.entry-content > .wp-block-kadence-rowlayout.alignfull {
	width: 100vw;
	max-width: 100vw;
	margin-left: calc(50% - 50vw);
	margin-right: calc(50% - 50vw);
}

.imc-hero .kt-inside-inner-col {
	text-align: center;
}
.imc-hero p,
.imc-hero h1,
.imc-hero .wp-block-kadence-advancedheading {
	margin-left: auto;
	margin-right: auto;
}
.imc-hero .wp-block-shortcode,
.imc-hero .imc-calc,
.imc-hero .wp-block-kadence-advancedbtn {
	text-align: initial;
}
.imc-section h2,
.imc-hero h1 {
	border-top: none;
	padding-top: 0;
	margin-top: 0;
}
.imc-section .kt-accordion-wrap,
.imc-section .wp-block-table,
.imc-section .wp-block-kadence-advancedheading,
.imc-section p,
.imc-section ul,
.imc-section ol {
	max-width: 68ch;
}

/* Trust badge row (added near the hero) */
.imc-trust-bar {
	display: flex;
	flex-wrap: wrap;
	gap: 10px;
	margin: 16px 0 24px;
	max-width: 560px;
	margin-left: auto;
	margin-right: auto;
}
.imc-trust-bar__item {
	display: inline-flex;
	align-items: center;
	gap: 6px;
	font-family: "IBM Plex Sans", sans-serif;
	font-size: 13px;
	font-weight: 500;
	color: var(--global-palette5);
	background: var(--global-palette8);
	border: 1px solid #DCE3E1;
	border-radius: 999px;
	padding: 6px 14px;
}
.imc-trust-bar__item::before {
	content: "";
	width: 6px;
	height: 6px;
	border-radius: 50%;
	background: var(--global-palette1);
	flex-shrink: 0;
}

@media (max-width: 599px) {
	.entry-content h2 { margin-top: 44px; }
}
